// CardItem.tsx
import React from "react";
import { Box, TextField, IconButton } from "@mui/material";
import cross from "../../assets/svg/cross.svg";
import { images } from "../../modules/exports/images";

interface Card {
  id: number;
  selectedImage: string | null;
}

interface CardItemProps {
  card: Card;
  onSelectImage: (id: number) => void;
  updateTaskDescription: (id: number, description: string) => void;
  deleteCard: (id: number) => void; // Функция для удаления карточки
  descriptionInputRef: React.RefObject<HTMLInputElement>;
}

export const CardItem: React.FC<CardItemProps> = ({
  card,
  onSelectImage,
  updateTaskDescription,
  deleteCard,
  descriptionInputRef,
}) => {
  const handleDelete = () => {
    if (card) {
      deleteCard(card.id); // Убедитесь, что карточка существует перед удалением
    }
  };

  return (
    <Box
      sx={{
        width: "100%",
        background: "#F5F5F5",
        borderRadius: "20px",
        display: "flex",
        alignItems: "center",
        flexDirection: "column",
        gap: "10px",
        padding: 0,
        transition: "all 0.3s ease",
        cursor: "grab",
        "&:active": {
          cursor: "grabbing",
        },
      }}
    >
      <Box
        sx={{
          width: "100%",
          minHeight: "130px",
          background: card.selectedImage ? `url(${card.selectedImage})` : "#7D8AA1",
          borderRadius: "20px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          backgroundSize: "cover",
          backgroundPosition: "center",
          padding: 0,
          position: "relative"
        }}
      >
        <img
          onClick={() => onSelectImage(card.id)}
          style={{ cursor: "pointer", marginRight: "10px" }}
          src={cross}
          alt="close"
        />
 <IconButton
  onClick={handleDelete}
  sx={{
    position: "absolute",
    right: 10,
    top: 0,
    color: "#FF0000",
  }}
>
  <Box
    component="img"
    sx={{
      width: "20px",
      opacity: 0.3,
      "&:hover": {
        opacity: 0.8,
      },
    }}
    src={images["bin"]}
    alt="Delete icon"
  />
</IconButton>
      </Box>

      <Box
        sx={{
          width: "100%",
          display: "flex",
          flexDirection: "column",
          textAlign: "left",
          gap: "5px",
          padding: 0,
        }}
      >
        <TextField
          multiline
          placeholder="Write the name of the task"
          onChange={(e) => updateTaskDescription(card.id, e.target.value)}
          minRows={1}
          maxRows={5}
          inputRef={descriptionInputRef}
          sx={{
            width: "100%",
            "& .MuiOutlinedInput-root": {
              border: "none",
              padding: 0,
              "& fieldset": {
                border: "none",
              },
              "&:hover fieldset": {
                border: "none",
              },
              "&.Mui-focused fieldset": {
                border: "none",
              },
            },
            "& .MuiInputBase-input": {
              padding: "10px",
              fontWeight: 900,
              color: "#394D70",
              minHeight: "30px",
            },
          }}
        />
        <TextField
          sx={{
            width: "100%",
            fontWeight: "600",
            color: "#394D70",
            opacity: 0.5,
            "& .MuiOutlinedInput-root": {
              padding: 0,
              border: "none",
              "& fieldset": {
                border: "none",
              },
              "&:hover fieldset": {
                border: "none",
              },
              "&.Mui-focused fieldset": {
                border: "none",
              },
            },
            "& .MuiInputBase-input": {
              padding: "10px",
              fontWeight: "600",
              color: "#394D70",
              border: "none",
              minHeight: "30px",
            },
            "& .MuiInputBase-inputMultiline": {
              border: "none",
              padding: "10px",
            },
            height: "auto",
          }}
          placeholder="Write what you need to do"
          multiline
          minRows={1}
          maxRows={5}
          onChange={(e) => updateTaskDescription(card.id, e.target.value)}
          inputRef={descriptionInputRef}
        />
      </Box>
    </Box>
  );
};
